mapper.update:
UPDATE support_program_sync_generation
SET latest_started_generation = #{generation}
WHERE source_code = #{sourceCode}

UPDATE support_program_sync_status
SET index_ready = TRUE
WHERE source_code = #{sourceCode}
  AND published_generation = #{publishedGeneration}
  AND published_catalog_fingerprint = #{catalogFingerprint}
  AND published_program_count = #{programCount}

UPDATE support_program_sync_status
SET index_ready = FALSE
WHERE source_code = #{sourceCode}
  AND published_generation = #{publishedGeneration}
  AND published_catalog_fingerprint = #{catalogFingerprint}
  AND published_program_count = #{programCount}
